// FreeLang GPT: Phase 1 - Tensor Operations
// ==================================================
// Core tensor computation module
// Status: 🟢 Implementation (Phase 1 Pilot)
// Tests: 20/20 target

module tensor

import math
import arrays

// ==================================================
// 1. TENSOR RECORD & METADATA
// ==================================================

// Tensor: N-dimensional array with shape and strides
record Tensor {
  data: Array[Float],    // 1D flattened data
  shape: Array[Int],     // dimensions [rows, cols, ...]
  strides: Array[Int],   // C-contiguous: [cols, 1] for 2D
  ndim: Int,             // number of dimensions
  size: Int              // total elements
}

// ==================================================
// 2. TENSOR CREATION
// ==================================================

// Create zero tensor
function zeros_tensor(shape: Array[Int]) -> Tensor = {
  let total_size = fold(shape, 1, fn(acc, dim) -> acc * dim)
  let data = fold_range(0, total_size, [], fn(acc, _) -> {
    append(acc, 0.0)
  })
  let strides = compute_strides(shape)

  Tensor {
    data: data,
    shape: shape,
    strides: strides,
    ndim: len(shape),
    size: total_size
  }
}

// Create ones tensor
function ones_tensor(shape: Array[Int]) -> Tensor = {
  let total_size = fold(shape, 1, fn(acc, dim) -> acc * dim)
  let data = fold_range(0, total_size, [], fn(acc, _) -> {
    append(acc, 1.0)
  })
  let strides = compute_strides(shape)

  Tensor {
    data: data,
    shape: shape,
    strides: strides,
    ndim: len(shape),
    size: total_size
  }
}

// Create random normal tensor (simplified: uniform [0,1] for now)
function randn_tensor(shape: Array[Int], seed: Int) -> Tensor = {
  let total_size = fold(shape, 1, fn(acc, dim) -> acc * dim)
  let data = fold_range(0, total_size, [], fn(acc, i) -> {
    let val = as_float((seed + i) % 100) / 100.0
    append(acc, val)
  })
  let strides = compute_strides(shape)

  Tensor {
    data: data,
    shape: shape,
    strides: strides,
    ndim: len(shape),
    size: total_size
  }
}

// ==================================================
// 3. STRIDE COMPUTATION (C-CONTIGUOUS)
// ==================================================

// Compute strides for C-contiguous layout
// Example: shape=[3,4] -> strides=[4,1]
function compute_strides(shape: Array[Int]) -> Array[Int] = {
  if len(shape) == 0 {
    []
  } else if len(shape) == 1 {
    [1]
  } else {
    let strides = []
    let stride = 1
    let rev_shape = reverse(shape)

    let result = fold(rev_shape, [], fn(acc, dim) -> {
      let new_stride = stride * dim
      append(acc, stride)
    })

    reverse(result)
  }
}

// Helper: reverse array
function reverse(arr: Array[Int]) -> Array[Int] = {
  let result = []
  fold_range(0, len(arr), result, fn(acc, i) -> {
    let idx = len(arr) - 1 - i
    append(acc, arr[idx])
  })
}

// ==================================================
// 4. TENSOR INDEXING (2D HELPER FUNCTIONS)
// ==================================================

// Convert 2D indices to 1D flat index
function tensor_index_2d(t: Tensor, i: Int, j: Int) -> Int = {
  i * t.shape[1] + j
}

// Get element at 2D position
function tensor_get_2d(t: Tensor, i: Int, j: Int) -> Float = {
  let idx = tensor_index_2d(t, i, j)
  t.data[idx]
}

// Set element at 2D position (returns new tensor)
function tensor_set_2d(mutable t: Tensor, i: Int, j: Int, val: Float) -> Void = {
  let idx = tensor_index_2d(t, i, j)
  t.data[idx] = val
}

// ==================================================
// 5. TENSOR OPERATIONS
// ==================================================

// Element-wise addition
function tensor_add(a: Tensor, b: Tensor) -> Tensor = {
  let result_data = []
  let result = fold_range(0, a.size, result_data, fn(acc, i) -> {
    append(acc, a.data[i] + b.data[i])
  })

  Tensor {
    data: result,
    shape: a.shape,
    strides: a.strides,
    ndim: a.ndim,
    size: a.size
  }
}

// Element-wise scalar multiplication
function tensor_scale(t: Tensor, scalar: Float) -> Tensor = {
  let result_data = []
  let result = fold_range(0, t.size, result_data, fn(acc, i) -> {
    append(acc, t.data[i] * scalar)
  })

  Tensor {
    data: result,
    shape: t.shape,
    strides: t.strides,
    ndim: t.ndim,
    size: t.size
  }
}

// Element-wise multiplication
function tensor_mul(a: Tensor, b: Tensor) -> Tensor = {
  let result_data = []
  let result = fold_range(0, a.size, result_data, fn(acc, i) -> {
    append(acc, a.data[i] * b.data[i])
  })

  Tensor {
    data: result,
    shape: a.shape,
    strides: a.strides,
    ndim: a.ndim,
    size: a.size
  }
}

// ==================================================
// 6. MATRIX MULTIPLICATION (2D ONLY)
// ==================================================

// Matrix multiplication: (m x n) @ (n x k) -> (m x k)
function matmul_2d(a: Tensor, b: Tensor) -> Tensor = {
  let m = a.shape[0]
  let n = a.shape[1]
  let k = b.shape[1]

  let result = zeros_tensor([m, k])

  // Nested loops: result[i,j] = sum(a[i,:] * b[:,j])
  fold_range(0, m, result, fn(res, i) -> {
    fold_range(0, k, res, fn(res2, j) -> {
      // Compute dot product: a[i,:] . b[:,j]
      let dot_product = fold_range(0, n, 0.0, fn(acc, p) -> {
        let a_val = tensor_get_2d(a, i, p)
        let b_val = tensor_get_2d(b, p, j)
        acc + (a_val * b_val)
      })

      tensor_set_2d(res2, i, j, dot_product)
      res2
    })
  })
}

// ==================================================
// 7. UTILITY FUNCTIONS
