// FreeLang GPT: Phase 2 - Automatic Differentiation
// ==================================================
// Autodiff engine with forward/backward pass and topological sort
// Status: 🟢 Implementation (Phase 2 Pilot)

module autograd

import tensor
import math

// ==================================================
// 1. OPERATION TYPES (UNION)
// ==================================================

// Supported operations for gradient computation
type OpType =
  | LeafOp
  | AddOp
  | MulOp
  | MatMulOp
  | ReLUOp
  | TanhOp
  | SoftmaxOp
  | SubtractOp

// ==================================================
// 2. VARIABLE RECORD (TENSOR WITH GRADIENTS)
// ==================================================

// Variable: Tensor + gradient tracking
record Variable {
  data: Tensor,              // Forward pass data
  mutable grad: Option[Tensor], // Accumulated gradient
  requires_grad: Bool,       // Track gradient?
  node_id: Int              // Unique identifier
}

// ==================================================
// 3. COMPUTE NODE (OPERATION IN GRAPH)
// ==================================================

// ComputeNode: Single operation in computational graph
record ComputeNode {
  output_id: Int,           // Output variable ID
  op: OpType,               // Operation type
  input_ids: Array[Int],    // Input variable IDs
  metadata: Array[Float]    // Shape info, epsilon, etc.
}

// ==================================================
// 4. COMPUTE GRAPH (FULL DAG)
// ==================================================

// ComputeGraph: Directed acyclic graph of operations
record ComputeGraph {
  variables: Array[Variable],
  nodes: Array[ComputeNode],
  next_id: Int              // ID counter for new variables
}

// ==================================================
// 5. GRAPH CONSTRUCTION
// ==================================================

// Create empty compute graph
function create_graph() -> ComputeGraph = {
  ComputeGraph {
    variables: [],
    nodes: [],
    next_id: 0
  }
}

// Register variable in graph
function register_variable(mutable graph: ComputeGraph, data: Tensor, requires_grad: Bool) -> Int = {
  let id = graph.next_id
  let var = Variable {
    data: data,
    grad: None,
    requires_grad: requires_grad,
    node_id: id
  }

  graph.variables = append(graph.variables, var)
  graph.next_id = graph.next_id + 1

  id
}

// ==================================================
// 6. FORWARD PASS OPERATIONS
// ==================================================

// Forward: Addition
function forward_add(mutable graph: ComputeGraph, a_id: Int, b_id: Int) -> Int = {
  let a = graph.variables[a_id]
  let b = graph.variables[b_id]
  let result = tensor_add(a.data, b.data)

  let output_id = register_variable(graph, result, true)

  let node = ComputeNode {
    output_id: output_id,
    op: AddOp,
    input_ids: [a_id, b_id],
    metadata: []
  }

  graph.nodes = append(graph.nodes, node)
  output_id
}

// Forward: Element-wise multiplication
function forward_mul(mutable graph: ComputeGraph, a_id: Int, b_id: Int) -> Int = {
  let a = graph.variables[a_id]
  let b = graph.variables[b_id]
  let result = tensor_mul(a.data, b.data)

  let output_id = register_variable(graph, result, true)

  let node = ComputeNode {
    output_id: output_id,
    op: MulOp,
    input_ids: [a_id, b_id],
    metadata: []
  }

  graph.nodes = append(graph.nodes, node)
  output_id
}

// Forward: Matrix multiplication
function forward_matmul(mutable graph: ComputeGraph, a_id: Int, b_id: Int) -> Int = {
  let a = graph.variables[a_id]
  let b = graph.variables[b_id]
  let result = matmul_2d(a.data, b.data)

  let output_id = register_variable(graph, result, true)

  let node = ComputeNode {
    output_id: output_id,
    op: MatMulOp,
    input_ids: [a_id, b_id],
    metadata: []
  }

  graph.nodes = append(graph.nodes, node)
  output_id
}

// Forward: ReLU activation
function forward_relu(mutable graph: ComputeGraph, x_id: Int) -> Int = {
  let x = graph.variables[x_id]
  let result = apply_relu(x.data)

  let output_id = register_variable(graph, result, true)

  let node = ComputeNode {
    output_id: output_id,
    op: ReLUOp,
    input_ids: [x_id],
    metadata: []
  }

  graph.nodes = append(graph.nodes, node)
  output_id
}

// Forward: Tanh activation
function forward_tanh(mutable graph: ComputeGraph, x_id: Int) -> Int = {
  let x = graph.variables[x_id]
  let result = apply_tanh(x.data)

  let output_id = register_variable(graph, result, true)

  let node = ComputeNode {
    output_id: output_id,
    op: TanhOp,
    input_ids: [x_id],
    metadata: []
  }

  graph.nodes = append(graph.nodes, node)
  output_id
}

// Forward: Softmax (numerically stable)
function forward_softmax(mutable graph: ComputeGraph, x_id: Int) -> Int = {
  let x = graph.variables[x_id]
  let result = apply_softmax(x.data)

  let output_id = register_variable(graph, result, true)

  let node = ComputeNode {
    output_id: output_id,
    op: SoftmaxOp,
    input_ids: [x_id],
    metadata: []
  }

  graph.nodes = append(graph.nodes, node)
  output_id
}

// Forward: Subtraction
function forward_subtract(mutable graph: ComputeGraph, a_id: Int, b_id: Int) -> Int = {
  let a = graph.variables[a_id]
  let b = graph.variables[b_id]
  let neg_b = tensor_scale(b.data, -1.0)
  let result = tensor_add(a.data, neg_b)

  let output_id = register_variable(graph, result, true)

  let node = ComputeNode {
    output_id: output_id,
    op: SubtractOp,
    input_ids: [a_id, b_id],
    metadata: []
  }

  graph.nodes = append(graph.nodes, node)
  output_id
}

// ==================================================
// 7. ACTIVATION FUNCTION HELPERS
// ==================================================

// Apply ReLU to tensor
function apply_relu(t: Tensor) -> Tensor = {
  let result_data = []
  let result = fold_range(0, t.size, result_data, fn(acc, i) -> {
    let val = t.data[i]
    let activated = if val > 0.0 { val } else { 0.0 }
    append(acc, activated)
  })

  Tensor {
    data: result,
    shape: t.shape,
    strides: t.strides,
    ndim: t.ndim,
    size: t.size
  }
}

// Apply Tanh to tensor
function apply_tanh(t: Tensor) -> Tensor = {
  let result_data = []
  let result = fold_range(0, t.size, result_data, fn(acc, i) -> {
    let val = tanh(t.data[i])
    append(acc, val)
  })

  Tensor {
    data: result,
    shape: t.shape,
    strides: t.strides,
    ndim: t.ndim,
    size: t.size
  }
}

// Apply softmax to tensor (numerically stable)
function apply_softmax(t: Tensor) -> Tensor = {
  // Find max for numerical stability
  let max_val = fold_range(0, t.size, t.data[0], fn(acc, i) -> {
    let val = t.data[i]
    if val > acc { val } else { acc }
  })

  // Compute exp(x - max)
  let exp_data = []
  let exp_vals = fold_range(0, t.size, exp_data, fn(acc, i) -> {
    let shifted = t.data[i] - max_val
    let exp_val = exp(shifted)
    append(acc, exp_val)
  })

  // Compute sum of exps
  let sum_exp = fold_range(0, len(exp_vals), 0.0, fn(acc, i) -> {
    acc + exp_vals[i]
  })

  // Divide by sum (normalization)
  let result_data = []
  let result = fold_range(0, len(exp_vals), result_data, fn(acc, i) -> {
    let prob = exp_vals[i] / sum_exp
    append(acc, prob)
  })

  Tensor {
    data: result,
    shape: t.shape,
    strides: t.strides,
    ndim: t.ndim,
    size: t.size
  }
}

// ==================================================
// 8. TOPOLOGICAL SORT (DFS-BASED)
// ==================================================

// Topological sort of computational graph (DFS)
function topological_sort(graph: ComputeGraph) -> Array[Int] = {
  let visited = []
  let sorted = []

  let visited_all = fold_range(0, len(graph.nodes), visited, fn(acc, i) -> {
    dfs_visit(graph, i, acc, fn(v, a) -> { append(a, v) })
  })

  sorted
}

// DFS visit helper (simplified version)
function dfs_visit(graph: ComputeGraph, node_idx: Int, mutable visited: Array[Int], mutable callback: fn(Int, Array[Int]) -> Array[Int]) -> Array[Int] = {
  // Mark as visited
  visited = append(visited, node_idx)
  callback(node_idx, visited)
}

// Topological order (simple reverse order for now)
function get_topo_order(graph: ComputeGraph) -> Array[Int] = {
  let order = []
  fold_range(0, len(graph.nodes), order, fn(acc, i) -> {
    let idx = len(graph.nodes) - 1 - i
    append(acc, idx)
  })
}

// ==================================================
// 9. BACKWARD PASS (GRADIENT COMPUTATION)
// ==================================================

// Backward: Compute gradients via chain rule
function backward(mutable graph: ComputeGraph, output_id: Int) -> Void = {
  // Initialize output gradient to 1.0
  let output_grad = ones_tensor(graph.variables[output_id].data.shape)
  graph.variables[output_id].grad = Some(output_grad)

  // Process nodes in reverse topological order
  let topo_order = get_topo_order(graph)
  fold_range(0, len(topo_order), (), fn(_, i) -> {
    let node_idx = topo_order[i]
    let node = graph.nodes[node_idx]

    // Get output gradient
    let output_var = graph.variables[node.output_id]
    let out_grad = match output_var.grad {
      Some(g) -> g,
      None -> zeros_tensor(output_var.data.shape)
    }

    // Compute input gradients based on operation type
    match node.op {
      AddOp -> {
        // d(a+b)/da = 1, d(a+b)/db = 1
        backprop_add(graph, node, out_grad)
      },
      MulOp -> {
        // d(a*b)/da = b, d(a*b)/db = a
        backprop_mul(graph, node, out_grad)
      },
      MatMulOp -> {
        // d(A@B)/dA = dL/dC @ B^T, d(A@B)/dB = A^T @ dL/dC
        backprop_matmul(graph, node, out_grad)
      },
      ReLUOp -> {
        // d(ReLU(x))/dx = (x > 0 ? 1 : 0)
        backprop_relu(graph, node, out_grad)
      },
      TanhOp -> {
        // d(tanh(x))/dx = 1 - tanh(x)^2
        backprop_tanh(graph, node, out_grad)
      },
      SubtractOp -> {
        // d(a-b)/da = 1, d(a-b)/db = -1
        backprop_subtract(graph, node, out_grad)
      },
      _ -> {}
    }
  })
}

// Backprop: Addition
function backprop_add(mutable graph: ComputeGraph, node: ComputeNode, out_grad: Tensor) -> Void = {
  let a_id = node.input_ids[0]
  let b_id = node.input_ids[1]

  // Gradient w.r.t. a = dL/dC (pass through)
  let a_var = graph.variables[a_id]
  let a_grad = match a_var.grad {
    Some(g) -> tensor_add(g, out_grad),
    None -> out_grad
  }
  graph.variables[a_id].grad = Some(a_grad)

  // Gradient w.r.t. b = dL/dC (pass through)
  let b_var = graph.variables[b_id]
  let b_grad = match b_var.grad {
    Some(g) -> tensor_add(g, out_grad),
    None -> out_grad
  }
  graph.variables[b_id].grad = Some(b_grad)
}

// Backprop: Element-wise multiplication
function backprop_mul(mutable graph: ComputeGraph, node: ComputeNode, out_grad: Tensor) -> Void = {
  let a_id = node.input_ids[0]
  let b_id = node.input_ids[1]

  let a = graph.variables[a_id].data
  let b = graph.variables[b_id].data

  // Gradient w.r.t. a = dL/dC * b
  let a_grad_contrib = tensor_mul(out_grad, b)
  let a_var = graph.variables[a_id]
  let a_grad = match a_var.grad {
    Some(g) -> tensor_add(g, a_grad_contrib),
    None -> a_grad_contrib
  }
  graph.variables[a_id].grad = Some(a_grad)

  // Gradient w.r.t. b = dL/dC * a
  let b_grad_contrib = tensor_mul(out_grad, a)
  let b_var = graph.variables[b_id]
  let b_grad = match b_var.grad {
    Some(g) -> tensor_add(g, b_grad_contrib),
    None -> b_grad_contrib
  }
  graph.variables[b_id].grad = Some(b_grad)
}

// Backprop: Matrix multiplication
function backprop_matmul(mutable graph: ComputeGraph, node: ComputeNode, out_grad: Tensor) -> Void = {
  let a_id = node.input_ids[0]
  let b_id = node.input_ids[1]

  let a = graph.variables[a_id].data
  let b = graph.variables[b_id].data

  // dL/dA = dL/dC @ B^T
  let b_t = transpose_2d(b)
  let a_grad_contrib = matmul_2d(out_grad, b_t)

  let a_var = graph.variables[a_id]
  let a_grad = match a_var.grad {
    Some(g) -> tensor_add(g, a_grad_contrib),
    None -> a_grad_contrib
  }
  graph.variables[a_id].grad = Some(a_grad)

  // dL/dB = A^T @ dL/dC
  let a_t = transpose_2d(a)
  let b_grad_contrib = matmul_2d(a_t, out_grad)

  let b_var = graph.variables[b_id]
  let b_grad = match b_var.grad {
    Some(g) -> tensor_add(g, b_grad_contrib),
    None -> b_grad_contrib
  }
  graph.variables[b_id].grad = Some(b_grad)
}

// Backprop: ReLU
function backprop_relu(mutable graph: ComputeGraph, node: ComputeNode, out_grad: Tensor) -> Void = {
  let x_id = node.input_ids[0]
  let x = graph.variables[x_id].data

  // d(ReLU(x))/dx = (x > 0 ? 1 : 0)
  let mask_data = []
  let mask = fold_range(0, x.size, mask_data, fn(acc, i) -> {
    let val = if x.data[i] > 0.0 { 1.0 } else { 0.0 }
    append(acc, val)
  })

  let mask_tensor = Tensor {
    data: mask,
    shape: x.shape,
    strides: x.strides,
    ndim: x.ndim,
    size: x.size
  }

  let grad_contrib = tensor_mul(out_grad, mask_tensor)
  let x_var = graph.variables[x_id]
  let x_grad = match x_var.grad {
    Some(g) -> tensor_add(g, grad_contrib),
    None -> grad_contrib
  }
  graph.variables[x_id].grad = Some(x_grad)
}

// Backprop: Tanh
function backprop_tanh(mutable graph: ComputeGraph, node: ComputeNode, out_grad: Tensor) -> Void = {
  let x_id = node.input_ids[0]
  let y = graph.variables[node.output_id].data

  // d(tanh(x))/dx = 1 - tanh(x)^2
  let grad_data = []
  let grad_func = fold_range(0, y.size, grad_data, fn(acc, i) -> {
    let tanh_y = y.data[i]
    let deriv = 1.0 - (tanh_y * tanh_y)
    append(acc, deriv)
  })

  let grad_func_tensor = Tensor {
    data: grad_func,
    shape: y.shape,
    strides: y.strides,
    ndim: y.ndim,
    size: y.size
  }

  let grad_contrib = tensor_mul(out_grad, grad_func_tensor)
  let x_var = graph.variables[x_id]
  let x_grad = match x_var.grad {
    Some(g) -> tensor_add(g, grad_contrib),
