// Backprop: Subtraction
function backprop_subtract(mutable graph: ComputeGraph, node: ComputeNode, out_grad: Tensor) -> Void = {
  let a_id = node.input_ids[0]
  let b_id = node.input_ids[1]

  // d(a-b)/da = 1
  let a_var = graph.variables[a_id]
