// FreeLang GPT: Phase 2 - Autograd Tests
// ==================================================
// Test suite for automatic differentiation
// Status: 🟢 Testing (20+ test cases)

module test_autograd

import tensor
import autograd

// ==================================================
// 1. GRAPH CONSTRUCTION TESTS
// ==================================================

function test_create_graph() -> Bool = {
  let graph = create_graph()
