// ==================================================

// Finite difference approximation: (f(x+h) - f(x-h)) / (2h)
function numerical_gradient(f: fn(Tensor) -> Tensor, x: Tensor, h: Float) -> Tensor = {
  let grad_data = []
  let grad = fold_range(0, x.size, grad_data, fn(acc, i) -> {
